import json, hashlib, html
from pathlib import Path
from datetime import datetime, timezone
P=Path(__file__).resolve().parent
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,x): (P/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
for version in ['plant-candidates-v76','plant-image-audit-v77']:
 b=P.parent/version
 assert all(sha(b/n)==h for n,h in json.loads((b/'FREEZE.json').read_text())['files'].items())
B=P.parent/'plant-image-audit-v77'
prior=json.loads((B/'AUDIT.json').read_text(encoding='utf-8'))
slots=[s for s in json.loads((B/'H-F-SLOTS.json').read_text(encoding='utf-8')) if s['page'] in ['f6v','f9v']]
assert {(s['page'],s['transcription'],s['first_token']) for s in slots}=={('f6v','H','koar'),('f6v','F','koary'),('f9v','H','fochor'),('f9v','F','fochor')}
images=[dict(page='f6v',oid='1006087',resolution=[2753,3797],regions=['full/1400,','1300,600,1100,1800/900,','1750,850,650,650/full'],observed='Deeply divided star-like leaves with small marginal teeth; branching stalks bearing round heads outlined with long pointed projections. Native-resolution heads have green centres and blue rims.',support='The combination of palmately divided leaves and prickly-looking heads remains compatible with castor.',limits='A three-part capsule is not demonstrated. Colour boundaries are not capsule sutures. Individual pedicelled balls and long peripheral projections could represent other heads; peltate attachment is not securely proven. No reproductive sex or seed diagnostic established.',decision='Ricinus communis retained as provisional candidate, not confirmed.'),dict(page='f9v',oid='1006093',resolution=[2812,3797],regions=['full/1400,','1200,500,1400,2200/1000,','2200,700,500,550/full'],observed='Five-part flower outlines, blue and yellow paint; broad lanceolate lower leaves and deeply divided upper leaf-like structures. The native-resolution upper-right flower has one upper lobe, two lateral and two lower lobes, one lower lobe yellowish.',support='Different lower/upper foliage forms and five-part coloured flowers support a Viola/pansy comparison.',limits='Divided structures cannot securely be assigned as stipules rather than leaves. No diagnostic spur established. The drawing does not cleanly show the usual two-upper/one-lower pansy petal arrangement; orientation and stylization remain alternatives. Species and modern subspecies unresolved.',decision='Viola, with V. tricolor as a candidate, retained; no exact species anchor.')]
for a in images:
 a['manifest']='https://collections.library.yale.edu/manifests/2002046'
 a['image']='https://collections.library.yale.edu/iiif/2/'+a['oid']+'/full/full/0/default.jpg'
 a['review']='Direct browser inspection of overview, enlarged region, and native-resolution crop. Dimensions and folio labels verified against Yale IIIF manifest. No image files downloaded.'
 a['alternatives']=next(x['alternatives'] for x in prior if x['page']==a['page'])
 a['independence']='Researcher assessment after exposure to proposed identities; not blinded botanical identification. ELV provenance and alternatives retained from v77.'
names=[dict(page='f6v',forms=['Palma Christi'],date=1485,period='late medieval print; later than the usual early-fifteenth-century Voynich dating',work='Gart der Gesundheit, Mainz',locator='chapter 310; BSB bsb00032739 image 498',url='https://daten.digitale-sammlungen.de/bsb00032739/image_498',verification='Printed heading and descriptive passage inspected directly in enlarged facsimile; BSB bibliographic record gives Mentz 1485.',spelling='Palma Christi is an expanded reading of the abbreviated printed heading; not a diplomatic character string. No pronunciation supplied.',fit='Historical castor candidate: palmately divided leaves in illustration and text comparing leaves to vine leaves. Historical depiction is stylized and does not independently establish f6v identity.',status='Admitted as a dated, conditional name candidate; abbreviation expansion explicit.',ambiguity='Palma Christi is not an exclusive botanical identifier across all traditions. This witness does not establish use in the Voynich region or before 1485.'),dict(page='f9v',forms=['Iacea','freyschem krut'],date=1485,period='late medieval print; later than the usual early-fifteenth-century Voynich dating',work='Gart der Gesundheit, Mainz',locator='chapter 432; BSB bsb00032739 image 674',url='https://daten.digitale-sammlungen.de/bsb00032739/image_674',verification='Heading and adjacent description inspected directly in enlarged facsimile; same dated BSB volume.',spelling='Reader transcription with long-s normalized. Iacea/Jacea is an orthographic reading alternative, not two independent names. Word division freyschem krut retained; exact diplomatic spelling requires specialist review.',fit='Text describes three flower colours (yellow, blue, white); woodcut has divided leaf-like structures and violet-like flowers. Supports pansy context, not modern taxonomic precision.',status='Admitted as dated conditional candidates, with orthographic uncertainty.',ambiguity='Iacea/Jacea is not universally exclusive to pansy. Botanical context must accompany this form. Freyschem nomenclature has a therapeutic context; no inference that every similarly named plant is Viola tricolor.')]
leads=[dict(forms=['Cici','kiki','Arbor mirabilis'],status='Not admitted from ELV synonym list: twentieth-century list is not a medieval witness.'),dict(forms=['Palma Christi in Trinity O.2.48'],status='Fourteenth-century manuscript catalogue verified, but proposed folio/name passage not resolved; not admitted as an earlier witness.',url='https://mss-cat.trin.cam.ac.uk/Manuscript/O.2.48'),dict(forms=['Jacea (1491)','Palma Christi (1491)'],status='Located in references to Hortus sanitatis chapters 511 and 330; primary page text not inspected in this pass. Not extra independent confirmation.',urls=['https://daten.digitale-sammlungen.de/bsb00027846/image_486','https://daten.digitale-sammlungen.de/bsb00027846/image_302']),dict(forms=['Pances','Loue in idlenes','Hartes ease'],date=1578,status='Later English comparison only. Reported by Marissa Nicosia quoting Dodoens/Lyte p148; original passage not inspected. Excluded from admitted candidate set.',url='https://rarecooking.com/tag/pansy/'),dict(forms=['Uiola'],status='Earlier CELT record remains preserved, but its sweet-violet interpretation is not a clean pansy anchor.' )]
rules={'state':'Frozen candidate audit before sound fitting; not a qualified decipherment experiment','selection':'Only f6v and f9v; first paragraph-first token inherited unchanged from v76/v77. Do not search later tokens for a better name match.','transcriptions':'H/F are alternate readings of one manuscript, not independent replication. koar/koary retained without stripping final y.','admitted_name_records':2,'sound_mappings':None,'no_sound_fit':True,'heldout_warning':'Both folios and their words have already been examined. Neither is untouched confirmatory evidence for a future sound mapping.','candidate_policy':'All name alternatives and expansions must remain visible. A future fitting test must freeze orthographic normalization, language/period restrictions, multiplicity correction and genuinely withheld examples before fitting. No automatic matching authorized or performed here.','independence':'The two dated entries belong to one 1485 herbal, not two independent traditions. Visual resemblance and name attestation are separate claims.','failures':['Yale web fetch 403; browser IIIF succeeded','Shell network DNS failed','Trinity early-name locator unresolved','No exact botanical species confirmed','No period pronunciation established','No fifteenth-century name proves that a paragraph opening is a plant name']}
save('IMAGE-AUDIT.json',images);save('HISTORICAL-NAMES.json',names);save('UNADMITTED-LEADS.json',leads);save('H-F-SLOTS.json',slots);save('RULES.json',rules)
e=lambda x:html.escape(str(x))
out=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Plant details and dated names · v78</title><style>body{font:17px/1.6 system-ui;max-width:1050px;margin:36px auto;padding:0 24px;background:#10241f;color:#e7eee7}a{color:#a4e4bf}article,aside{padding:22px;border:1px solid #527264;border-radius:12px;margin:24px 0}h1,h2{color:#c9edb9}small{color:#bfcec5}code{color:#ffe0aa}dt{font-weight:bold;margin-top:12px}dd{margin-left:0}li{margin:8px 0}</style><h1>Plant details & dated names</h1><p>v78 · 23 October 2026 · Frozen before sound fitting</p><aside><b>Useful candidates, no identification or reading claimed.</b> Yale full scans and native-resolution detail crops inspected. Two entries in a 1485 herbal now supply dated conditional names. They are one source tradition and do not establish early-fifteenth-century local usage. No sound mappings fitted.</aside>']
for a,n in zip(images,names):
 out.append('<article><h2>'+a['page']+' · '+e(a['decision'])+'</h2><p>'+ ' / '.join(s['transcription']+': <code>'+e(s['first_token'])+'</code>' for s in slots if s['page']==a['page'])+'</p><p><a href="'+a['image']+'">Yale full scan</a> · '+e(a['resolution'])+' pixels</p><p>'+ ' · '.join('<a href="https://collections.library.yale.edu/iiif/2/'+a['oid']+'/'+r+'/0/default.jpg">View '+('native detail' if r.endswith('/full') else 'region '+str(i+1))+'</a>' for i,r in enumerate(a['regions']))+'</p><dl>')
 for key in ['observed','support','limits','alternatives','independence']:out.append('<dt>'+e(key.title())+'</dt><dd>'+e(a[key])+'</dd>')
 out.append('</dl><h3>'+e(' / '.join(n['forms']))+' · 1485</h3><p><a href="'+n['url']+'">'+e(n['work']+' — '+n['locator'])+'</a></p>')
 for key in ['verification','spelling','fit','ambiguity']:out.append('<p><b>'+key.title()+':</b> '+e(n[key])+'</p>')
 out.append('</article>')
out.append('<h2>Unadmitted names and preserved gaps</h2><ul>'+''.join('<li><b>'+e(' / '.join(l['forms']))+'</b>: '+e(l['status'])+'</li>' for l in leads)+'</ul><h2>Freeze boundaries</h2><ul>'+''.join('<li>'+e(rules[k])+'</li>' for k in ['selection','transcriptions','heldout_warning','candidate_policy','independence'])+'</ul><p>Full source lines and H/F disagreements: <a href="H-F-SLOTS.json">H/F record</a>. <a href="FREEZE.json">SHA-256 manifest</a>. <a href="../plant-image-audit-v77/report.html">Preserved v77 audit</a>.</p></html>')
(P/'report.html').write_text('\n'.join(out),encoding='utf-8')
save('VERIFICATION.json',{'prior_v76_v77_hashes_unchanged':True,'four_HF_records_equal_inherited_records':True,'image_manifest_labels_checked':True,'primary_1485_headings_visually_inspected':True,'blind_botanical_validation':False,'sound_fitting_performed':False})
save('FREEZE.json',{'utc':datetime.now(timezone.utc).isoformat(),'files':{f.name:sha(f) for f in sorted(P.iterdir()) if f.is_file() and f.name!='FREEZE.json'},'v77_manifest_sha256':sha(B/'FREEZE.json')})
assert all(sha(P/n)==h for n,h in json.loads((P/'FREEZE.json').read_text())['files'].items())
print('Frozen v78: two image audits, two dated name records, four unchanged H/F slots; no sound fitting.')
